pc.script.createLoadingScreen(function (app) {
    // ---------------------------------------------------------------------
    // Catch a Pet -- "Field Guide" loading screen.
    // Warm parchment surface + the game's clay accent + a ring of real
    // in-game animal icons swaying around the logo, matching the in-game UI
    // tokens (Code/Kimchi Tools/Core/UI/JS-UI/kimchiUiTokens.js).
    // Pre-boot: cannot read app.assets or the token CSS vars, so all art is
    // embedded as base64 WebP and the brand hex values are copied as literals.
    // PREVIOUS loading screen preserved at
    //   .claude/backups/loadingScreen.original.js   (local-only, never synced)
    // Roll back: copy that file back over loadingScreen.js.
    // ---------------------------------------------------------------------
    var USE_FAKE_PROGRESS = true;

    var LOGO_SRC = 'data:image/webp;base64,';
    var ANIMALS = {"icons": {"rabbit": "data:image/webp;base64,", "cat": "data:image/webp;base64,", "panda": "data:image/webp;base64,", "penguin": "data:image/webp;base64,", "fennecfox": "data:image/webp;base64,", "kangaroo": "data:image/webp;base64,", "elephant": "data:image/webp;base64,", "peacock": "data:image/webp;base64,", "octopus": "data:image/webp;base64,", "dragon": "data:image/webp;base64,", "pegasus": "data:image/webp;base64,", "kirin": "data:image/webp;base64,"}, "order": ["rabbit", "cat", "panda", "penguin", "fennecfox", "kangaroo", "elephant", "peacock", "octopus", "dragon", "pegasus", "kirin"]};   // { icons: {key:dataURI}, order: [key,...] }

    // Early-fetch hints: start Ammo/config/scene downloads now so they overlap
    // the engine boot instead of running serially.
    (function () {
        var addHint = function (href, as, crossorigin) {
            if (!href) return;
            var link = document.createElement('link');
            link.rel = 'preload'; link.as = as; link.href = href;
            if (crossorigin) link.crossOrigin = crossorigin;
            document.head.appendChild(link);
        };
        var prefix = window.ASSET_PREFIX || '';
        (window.PRELOAD_MODULES || []).forEach(function (m) {
            if (m.hasOwnProperty('preload') && !m.preload) return;
            if (m.moduleName === 'BASIS' || m.moduleName === 'DracoDecoderModule') return;
            addHint(prefix + m.glueUrl, 'script');
            addHint(prefix + m.wasmUrl, 'fetch', 'anonymous');
        });
        addHint(window.CONFIG_FILENAME, 'fetch', 'anonymous');
        addHint(window.SCENE_PATH, 'fetch', 'anonymous');
    })();

    var slotEls = [];
    var onResize = null;
    var tickInterval = null;

    var layout = function () {
        var W = window.innerWidth, H = window.innerHeight;
        var total = slotEls.length;
        var n = (W < 560) ? Math.min(8, total) : total;
        var cx = W / 2, cy = H / 2;
        var Rx = Math.max(150, Math.min(W * 0.40, 400));
        var Ry = Math.max(146, Math.min(H * 0.40, 320));
        for (var i = 0; i < total; i++) {
            slotEls[i].style.display = (i < n) ? 'block' : 'none';
        }
        for (var j = 0; j < n; j++) {
            var ang = (-90 + j * (360 / n)) * Math.PI / 180;
            slotEls[j].style.left = (cx + Rx * Math.cos(ang)) + 'px';
            slotEls[j].style.top  = (cy + Ry * Math.sin(ang)) + 'px';
        }
    };

    var createCss = function () {
        var css = [
            '#application-splash-wrapper {',
            '    position: absolute; top: 0; left: 0; height: 100%; width: 100%; overflow: hidden;',
            '    background: linear-gradient(180deg, #FBF4E4 0%, #F4EAD5 100%);',
            "    font-family: 'Fredoka', system-ui, -apple-system, 'Segoe UI', sans-serif;",
            '}',
            '#ct-page-frame {',
            '    position: absolute; border: 2px solid rgba(44,32,20,0.16); border-radius: 16px; z-index: 0;',
            '    pointer-events: none;',
            '    top: calc(14px + env(safe-area-inset-top)); left: calc(14px + env(safe-area-inset-left));',
            '    right: calc(14px + env(safe-area-inset-right)); bottom: calc(14px + env(safe-area-inset-bottom));',
            '}',
            '#ct-animals { position: absolute; inset: 0; z-index: 1; pointer-events: none; }',
            '.ct-animal-slot {',
            '    position: absolute; transform: translate(-50%, -50%);',
            '    animation: ct-appear 0.5s cubic-bezier(0.34,1.56,0.64,1) backwards;',
            '}',
            '.ct-animal-slot img {',
            '    display: block; width: clamp(56px, 8.5vw, 92px); height: auto;',
            "    filter: drop-shadow(0 4px 5px rgba(44,32,20,0.22));",
            '    will-change: transform; animation: ct-sway 2.8s ease-in-out infinite;',
            '}',
            '#application-splash {',
            '    position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);',
            '    width: 248px; max-width: 70vw; text-align: center; display: none; z-index: 2;',
            '}',
            '#ct-logo { width: 100%; display: block; }',
            '#ct-bar {',
            '    position: relative; width: 220px; max-width: 64vw; height: 16px; margin: 16px auto 0;',
            '    background: #F4EAD5; border: 2px solid #2C2014; border-radius: 999px;',
            '    box-shadow: inset 0 2px 6px rgba(44,32,20,0.22); overflow: hidden;',
            '}',
            '#ct-bar-fill { position: relative; overflow: hidden; width: 0%; height: 100%; border-radius: 999px; background: #E0673A; box-shadow: inset 0 -3px 0 #B5421F; transition: width 0.22s cubic-bezier(0.22,1,0.36,1); }',
            '#ct-bar-fill::after { content: \"\"; position: absolute; top: 0; left: 0; height: 100%; width: 55%; background: linear-gradient(100deg, transparent, rgba(255,233,168,0.55), transparent); animation: ct-sheen 1.05s linear infinite; }',
            '#ct-pct { margin: 6px auto 0; font-size: 12px; font-weight: 600; color: #2C2014; font-variant-numeric: tabular-nums; text-align: right; width: 220px; max-width: 64vw; }',
            '@keyframes ct-sway { 0%, 100% { transform: rotate(-9deg); } 50% { transform: rotate(9deg); } }',
            '@keyframes ct-sheen { 0% { transform: translateX(-130%); } 100% { transform: translateX(330%); } }',
            '@keyframes ct-appear { 0% { opacity: 0; transform: translate(-50%, -50%) scale(0.2); } 60% { opacity: 1; transform: translate(-50%, -50%) scale(1.12); } 100% { opacity: 1; transform: translate(-50%, -50%) scale(1); } }',
            '@media (max-width: 560px) { #application-splash { width: 200px; } #ct-bar, #ct-pct { width: 180px; } }',
            '@media (max-height: 430px) { #application-splash { transform: translate(-50%, -50%) scale(0.82); } }',
            '@media (prefers-reduced-motion: reduce) {',
            '    .ct-animal-slot, .ct-animal-slot img { animation: none !important; }',
            '    #ct-bar-fill { transition: none !important; }',
            '    #ct-bar-fill::after { animation: none !important; opacity: 0; }',
            '}'
        ].join('\n');
        var style = document.createElement('style');
        style.type = 'text/css';
        if (style.styleSheet) { style.styleSheet.cssText = css; }
        else { style.appendChild(document.createTextNode(css)); }
        document.head.appendChild(style);
    };

    var showSplash = function () {
        var wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';
        document.body.appendChild(wrapper);

        var frame = document.createElement('div');
        frame.id = 'ct-page-frame';
        wrapper.appendChild(frame);

        var animalsWrap = document.createElement('div');
        animalsWrap.id = 'ct-animals';
        wrapper.appendChild(animalsWrap);

        var order = ANIMALS.order, icons = ANIMALS.icons;
        for (var i = 0; i < order.length; i++) {
            var slot = document.createElement('div');
            slot.className = 'ct-animal-slot';
            slot.style.animationDelay = (0.1 + i * 0.07).toFixed(2) + 's';
            var img = document.createElement('img');
            img.src = icons[order[i]];
            img.style.animationDelay = (-(i * 0.27)).toFixed(2) + 's';
            img.style.animationDuration = (2.5 + (i % 4) * 0.28).toFixed(2) + 's';
            slot.appendChild(img);
            animalsWrap.appendChild(slot);
            slotEls.push(slot);
        }

        var splash = document.createElement('div');
        splash.id = 'application-splash';
        wrapper.appendChild(splash);

        var logo = document.createElement('img');
        logo.id = 'ct-logo';
        logo.src = LOGO_SRC;
        logo.onload = function () { splash.style.display = 'block'; };
        splash.appendChild(logo);

        var bar = document.createElement('div');
        bar.id = 'ct-bar';
        splash.appendChild(bar);
        var fill = document.createElement('div');
        fill.id = 'ct-bar-fill';
        bar.appendChild(fill);

        var pct = document.createElement('div');
        pct.id = 'ct-pct';
        pct.textContent = '0%';
        splash.appendChild(pct);

        layout();
        onResize = function () { layout(); };
        window.addEventListener('resize', onResize);
    };

    var hideSplash = function () {
        if (tickInterval) { clearInterval(tickInterval); tickInterval = null; }
        if (onResize) { window.removeEventListener('resize', onResize); onResize = null; }
        var w = document.getElementById('application-splash-wrapper');
        if (w && w.parentElement) { w.parentElement.removeChild(w); }
    };

    var fakeProgress = 0;
    var setBar = function (v) {
        v = Math.min(1, Math.max(0, v));
        var fill = document.getElementById('ct-bar-fill');
        var pct = document.getElementById('ct-pct');
        if (fill) { fill.style.width = (v * 100) + '%'; }
        if (pct) { pct.textContent = Math.round(v * 100) + '%'; }
    };
    // Designed pacing for the bar WHILE the game loads -- purely cosmetic, it
    // NEVER holds the screen up (the engine's hideLoadingScreen hides it at any %).
    // A DECELERATING ease-in: slow start, and an ever-slower approach to the top so
    // it does NOT hit 90% early -- it should still be mid-climb through a real load.
    // Tunables:
    var startTime = 0;
    var TAU_MS    = 7000;   // time-constant; bigger = slower climb. ~hits 90% near 2x this
    var CURVE_POW = 1.35;   // >1 = gentler, slower START
    var SOFT_CAP  = 0.97;   // asymptote ceiling (never implies "done" before the game shows)
    var HARD_CAP  = 0.98;   // absolute ceiling, incl. the anti-stall creep

    var startProgress = function () {
        startTime = Date.now();
        tickInterval = setInterval(function () {
            var elapsed = Date.now() - startTime;
            var x = Math.pow(elapsed / TAU_MS, CURVE_POW);     // gentle start
            var base = SOFT_CAP * (1 - Math.exp(-x));          // decelerating approach
            var target = Math.min(HARD_CAP, Math.max(base, fakeProgress + 0.0006)); // never stall
            if (target > fakeProgress) { fakeProgress = target; setBar(fakeProgress); }
        }, 60);
    };

    createCss();
    showSplash();
    startProgress();

    // Game is ready -> show it IMMEDIATELY, even mid-fill. No artificial delay.
    app.on('hideLoadingScreen', hideSplash);
});
